"""0098: no loops through a reference field that names its own kind.

A hierarchy has refused loops since 0006 (`relationship_validate`). A reference attribute whose
target is its own kind -- an employee's `manager`, a region's `parent` -- nests that kind in
itself exactly as a hierarchy does, but its mirror relationship was never a hierarchy, so a loop
(the boss reports to the intern) could be saved and only surfaced later as a model that makes no
sense. The same walk now runs for such a mirror, and its refusal names the attribute (`field`)
so the record form can put the message under the right control.

Data already looping is left as it is: the domain's quality checks list it. Saving one of
those records again refuses until one link of the loop is changed.
"""
from alembic import op

revision = "0098"
down_revision = "0097"
branch_labels = None
depends_on = None

_NEW = 'CREATE OR REPLACE FUNCTION public.relationship_validate()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\n        DECLARE rt relationship_type; v_attr text; v_nested boolean;\n        BEGIN\n            SELECT * INTO rt FROM relationship_type WHERE id = NEW.relationship_type_id;\n            -- A reference field\'s mirror whose two ends are one kind (an employee\'s manager, a\n            -- region\'s parent) nests that kind in itself just as a hierarchy does: no loops.\n            SELECT ad.name INTO v_attr FROM attribute_def ad WHERE ad.references_id = rt.id;\n            v_nested := rt.is_hierarchy OR (v_attr IS NOT NULL AND (entity_type_is_a(rt.from_type_id, rt.to_type_id)\n                                                                   OR entity_type_is_a(rt.to_type_id, rt.from_type_id)));\n            IF NOT entity_type_is_a((SELECT entity_type_id FROM entity WHERE id = NEW.from_entity_id), rt.from_type_id)\n            OR NOT entity_type_is_a((SELECT entity_type_id FROM entity WHERE id = NEW.to_entity_id), rt.to_type_id) THEN\n                RAISE EXCEPTION \'relationship "%": entity types do not match\', rt.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\n                              \'kind\',           \'type_mismatch\',\n                              \'field\',          rt.name,\n                              \'from_entity_id\', NEW.from_entity_id,\n                              \'to_entity_id\',   NEW.to_entity_id)::text;\n            END IF;\n            IF rt.cardinality IN (\'one_to_many\', \'one_to_one\') AND EXISTS (\n                SELECT 1 FROM relationship r WHERE r.relationship_type_id = rt.id\n                   AND r.to_entity_id = NEW.to_entity_id AND r.id IS DISTINCT FROM NEW.id) THEN\n                RAISE EXCEPTION \'relationship "%": target already has a source\', rt.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\n                              \'kind\',           \'cardinality\',\n                              \'field\',          rt.name,\n                              \'cardinality\',    rt.cardinality,\n                              \'to_entity_id\',   NEW.to_entity_id)::text;\n            END IF;\n            IF rt.cardinality IN (\'many_to_one\', \'one_to_one\') AND EXISTS (\n                SELECT 1 FROM relationship r WHERE r.relationship_type_id = rt.id\n                   AND r.from_entity_id = NEW.from_entity_id AND r.id IS DISTINCT FROM NEW.id) THEN\n                RAISE EXCEPTION \'relationship "%": source already has a target\', rt.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\n                              \'kind\',           \'cardinality\',\n                              \'field\',          rt.name,\n                              \'cardinality\',    rt.cardinality,\n                              \'from_entity_id\', NEW.from_entity_id)::text;\n            END IF;\n            IF v_nested AND (NEW.from_entity_id = NEW.to_entity_id OR EXISTS (\n                WITH RECURSIVE down AS (\n                    SELECT to_entity_id AS id FROM relationship\n                     WHERE relationship_type_id = rt.id\n                       AND from_entity_id = NEW.to_entity_id\n                       AND id IS DISTINCT FROM NEW.id\n                    UNION\n                    SELECT r.to_entity_id FROM relationship r JOIN down ON r.from_entity_id = down.id\n                     WHERE r.relationship_type_id = rt.id\n                       AND r.id IS DISTINCT FROM NEW.id)\n                SELECT 1 FROM down WHERE id = NEW.from_entity_id)) THEN\n                IF v_attr IS NOT NULL THEN\n                    RAISE EXCEPTION \'%: "%" would make a loop -- it is this record or one below it\', v_attr,\n                          (SELECT key FROM entity WHERE id = NEW.to_entity_id)\n                        USING ERRCODE = \'23514\',\n                              DETAIL  = jsonb_build_object(\n                                  \'kind\',           \'cycle\',\n                                  \'field\',          v_attr,\n                                  \'record\',         (SELECT key FROM entity WHERE id = NEW.from_entity_id),\n                                  \'from_entity_id\', NEW.from_entity_id,\n                                  \'to_entity_id\',   NEW.to_entity_id)::text;\n                END IF;\n                RAISE EXCEPTION \'relationship "%": would create a cycle\', rt.name\n                    USING ERRCODE = \'23514\',\n                          DETAIL  = jsonb_build_object(\n                              \'kind\',           \'cycle\',\n                              \'field\',          rt.name,\n                              \'from_entity_id\', NEW.from_entity_id,\n                              \'to_entity_id\',   NEW.to_entity_id)::text;\n            END IF;\n            RETURN NEW;\n        END $function$'

